// MARK: - Per-state lookup

// Strategy assignments (path-command structure + preview method overrides):
//   TRANSFORM (1): boline
//   MORPH     (2): body, bo

// Subpath counts per id (most are 1; stroke paths like hands have N).
private func subpathCount(forId id: String) -> Int {
    switch id {
    case "body": return 1
    case "bo": return 1
    case "boline": return 1
    default: return 1
    }
}

// Subpath-aware segment lookup. For each (id, subpathIndex, state) returns
// the parsed segments to feed into WatchPiboMorphShape. Out-of-range subpaths return [].
func segments(for id: String, subpath s: Int, in state: PiboVectorState) -> [WatchPiboMorphPathSegment] {
    switch (id, s, state) {
    case ("boline", 0, .default): return PathData.boline_default_sub0
    case ("boline", 0, .pigu): return PathData.boline_pigu_sub0
    case ("boline", 0, .weak): return PathData.boline_weak_sub0
    case ("boline", 0, .angry): return PathData.boline_angry_sub0
    case ("boline", 0, .boring): return PathData.boline_boring_sub0
    case ("boline", 0, .dive): return PathData.boline_dive_sub0
    case ("boline", 0, .tired): return PathData.boline_tired_sub0
    case ("boline", 0, .coolhide): return PathData.boline_coolhide_sub0
    case ("boline", 0, .muscle): return PathData.boline_muscle_sub0
    case ("boline", 0, .sleep_1): return PathData.boline_sleep_1_sub0
    case ("boline", 0, .sleep_2): return PathData.boline_sleep_2_sub0
    case ("boline", 0, .awake): return PathData.boline_awake_sub0
    default: return []
    }
}

func polygon(for id: String, in state: PiboVectorState) -> [CGPoint] {
    switch (id, state) {
    case ("body", .default): return PathData.body_default_poly
    case ("body", .pigu): return PathData.body_pigu_poly
    case ("body", .weak): return PathData.body_weak_poly
    case ("body", .angry): return PathData.body_angry_poly
    case ("body", .boring): return PathData.body_boring_poly
    case ("body", .dive): return PathData.body_dive_poly
    case ("body", .tired): return PathData.body_tired_poly
    case ("body", .coolhide): return PathData.body_coolhide_poly
    case ("body", .muscle): return PathData.body_muscle_poly
    case ("body", .sleep_1): return PathData.body_sleep_1_poly
    case ("body", .sleep_2): return PathData.body_sleep_2_poly
    case ("body", .awake): return PathData.body_awake_poly
    case ("bo", .default): return PathData.bo_default_poly
    case ("bo", .pigu): return PathData.bo_pigu_poly
    case ("bo", .weak): return PathData.bo_weak_poly
    case ("bo", .angry): return PathData.bo_angry_poly
    case ("bo", .boring): return PathData.bo_boring_poly
    case ("bo", .dive): return PathData.bo_dive_poly
    case ("bo", .tired): return PathData.bo_tired_poly
    case ("bo", .coolhide): return PathData.bo_coolhide_poly
    case ("bo", .muscle): return PathData.bo_muscle_poly
    case ("bo", .sleep_1): return PathData.bo_sleep_1_poly
    case ("bo", .sleep_2): return PathData.bo_sleep_2_poly
    case ("bo", .awake): return PathData.bo_awake_poly
    default: return []
    }
}

// Per-state flat fills (ids whose color differs across states). Driven by
// the animated `fillState`, so SwiftUI interpolates the color with the
// morph — mirrors the JS engine's runFillTween.
private func fillColor(for id: String, in state: PiboVectorState) -> Color {
    switch (id, state) {
    case ("bo", .default): return Color(.sRGB, red: 0.12549, green: 0.57647, blue: 0.47843, opacity: 1)
    case ("bo", .pigu): return Color(.sRGB, red: 0.12549, green: 0.57647, blue: 0.47843, opacity: 1)
    case ("bo", .weak): return Color(.sRGB, red: 0.62745, green: 0.46667, blue: 0.07059, opacity: 1)
    case ("bo", .angry): return Color(.sRGB, red: 0.12549, green: 0.57647, blue: 0.47843, opacity: 1)
    case ("bo", .boring): return Color(.sRGB, red: 0.12549, green: 0.57647, blue: 0.47843, opacity: 1)
    case ("bo", .dive): return Color(.sRGB, red: 0.12549, green: 0.57647, blue: 0.47843, opacity: 1)
    case ("bo", .tired): return Color(.sRGB, red: 0.12549, green: 0.57647, blue: 0.47843, opacity: 1)
    case ("bo", .coolhide): return Color(.sRGB, red: 0.25882, green: 0.64314, blue: 0.52549, opacity: 1)
    case ("bo", .muscle): return Color(.sRGB, red: 0.12549, green: 0.57647, blue: 0.47843, opacity: 1)
    case ("bo", .sleep_1): return Color(.sRGB, red: 0.12549, green: 0.57647, blue: 0.47843, opacity: 1)
    case ("bo", .sleep_2): return Color(.sRGB, red: 0.12549, green: 0.57647, blue: 0.47843, opacity: 1)
    case ("bo", .awake): return Color(.sRGB, red: 0.12549, green: 0.57647, blue: 0.47843, opacity: 1)
    default: return Color.gray
    }
}

// Returns true if this shared id uses the polygon (MORPH) renderer.
private func isPolyMorph(_ id: String) -> Bool {
    switch id {
    case "body": return true
    case "bo": return true
    default: return false
    }
}




